import {body,first,snapshot,testEnabled} from '../shared.ts';
const secret=Deno.env.get('ROADSHOP_STRIPE_TEST_WEBHOOK_SECRET')||'';
export async function verify(raw:string,header:string,now=Date.now()){const parts=header.split(',').map(x=>x.trim().split('=')),times=parts.filter(x=>x[0]==='t').map(x=>x[1]);if(times.length!==1||!/^\d+$/.test(times[0])||Math.abs(now/1000-Number(times[0]))>300||!secret.startsWith('whsec_'))return false;const signatures=parts.filter(x=>x[0]==='v1'&&/^[0-9a-f]{64}$/i.test(x[1]||''));const enc=new TextEncoder(),k=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);for(const [,s] of signatures){const b=Uint8Array.from(s.match(/../g)!,x=>parseInt(x,16));if(await crypto.subtle.verify('HMAC',k,b,enc.encode(times[0]+'.'+raw)))return true}return false}
Deno.serve(async(req:Request)=>{if(req.method!=='POST')return new Response('POST required',{status:405});if(!testEnabled()||!secret)return new Response('Test webhook disabled',{status:503});try{const raw=await body(req,1000000);if(!await verify(raw,req.headers.get('stripe-signature')||''))return new Response('Invalid signature',{status:400});const e=JSON.parse(raw);if(e.livemode!==false)return new Response('Live event rejected',{status:400});if(!['checkout.session.completed','customer.subscription.created','customer.subscription.updated','customer.subscription.deleted','customer.subscription.paused','customer.subscription.resumed','invoice.paid','invoice.payment_failed'].includes(e.type))return new Response('Ignored');if(typeof e.id!=='string'||!/^evt_[A-Za-z0-9]+$/.test(e.id))return new Response('Invalid event',{status:400});if(await first('rs_events?select=event_id&event_id=eq.'+e.id))return new Response('Already processed');const c=e.data?.object?.customer;if(typeof c!=='string'||!/^cus_[A-Za-z0-9]+$/.test(c))return new Response('Invalid customer',{status:400});const s=await first('rs_subscriptions?select=user_id&customer_id=eq.'+c);if(!s)return new Response('Unknown customer; retry',{status:503});await snapshot(s.user_id,c,e);return new Response('OK')}catch{return new Response('Webhook processing unavailable; retry',{status:503})}});
